{
  "name": "Protect default branch",
  "target": "branch",
  "enforcement": "active",
  "conditions": {
    "ref_name": {
      "include": [
        "~DEFAULT_BRANCH"
      ],
      "exclude": []
    }
  },
  "rules": [
    {
      "type": "deletion"
    },
    {
      "type": "non_fast_forward"
    },
    {
      "type": "pull_request",
      "parameters": {
        "required_approving_review_count": 1,
        "dismiss_stale_reviews_on_push": true,
        "require_code_owner_review": false,
        "require_last_push_approval": false,
        "required_review_thread_resolution": false
      }
    }
  ],
  "bypass_actors": []
}

# Last match wins: broad rules first, specific paths after.
# In an org, name a team instead: @your-org/maintainers
/.github/              {maintainer}
/SECURITY.md           {maintainer}

# Release and packaging config
/package.json          {maintainer}
/pyproject.toml        {maintainer}
/Cargo.toml            {maintainer}
/.goreleaser.yaml      {maintainer}
/scripts/release/      {maintainer}

brew install scorecard        # or download a release binary
export GITHUB_AUTH_TOKEN=$(gh auth token)
scorecard --repo=github.com/{owner}/{repo} --show-details
